// Generated by vibes-espmatter – the Wi-Fi settings of the web interface (only with the HTTP server).
#include "espm_wifi.h"
#include "espm_config.h"
#include "espm_web.h"

#include <cstring>
#include <esp_mac.h>
#include <esp_netif.h>
#include <esp_wifi.h>

static const char *auth_name(wifi_auth_mode_t mode)
{
    switch (mode) {
    case WIFI_AUTH_OPEN: return "open";
    case WIFI_AUTH_WEP: return "WEP";
    case WIFI_AUTH_WPA3_PSK: return "WPA3";
    case WIFI_AUTH_WPA2_WPA3_PSK: return "WPA2/WPA3";
    case WIFI_AUTH_WPA2_ENTERPRISE:
    case WIFI_AUTH_WPA3_ENTERPRISE:
    case WIFI_AUTH_WPA2_WPA3_ENTERPRISE: return "enterprise";
    default: return "WPA2";
    }
}

/** Connection, addresses and MAC (the status badge and panel of the web interface). */
static esp_err_t wifi_status(httpd_req_t *req)
{
    if (!mesp_web_authorized(req)) return ESP_OK;
    Json j;
    j.obj();
    wifi_ap_record_t ap;
    if (esp_wifi_sta_get_ap_info(&ap) == ESP_OK) {
        j.key("connected").boolean(true);
        j.key("ssid").str((const char *)ap.ssid);
        j.key("rssi").num(ap.rssi);
        j.key("channel").num(ap.primary);
    } else {
        j.key("connected").boolean(false);
    }
    esp_netif_t *netif = esp_netif_get_handle_from_ifkey("WIFI_STA_DEF");
    esp_netif_ip_info_t ip;
    if (netif && esp_netif_get_ip_info(netif, &ip) == ESP_OK) {
        char buf[16];
        snprintf(buf, sizeof(buf), IPSTR, IP2STR(&ip.ip));
        j.key("ip").str(buf);
    }
    if (netif) {
        esp_ip6_addr_t ip6[8];
        int n = esp_netif_get_all_ip6(netif, ip6);
        j.key("ip6").arr();
        for (int i = 0; i < n; i++) {
            char buf[48];
            snprintf(buf, sizeof(buf), IPV6STR, IPV62STR(ip6[i]));
            j.str(buf);
        }
        j.end_arr();
    }
    uint8_t mac[6];
    if (esp_read_mac(mac, ESP_MAC_WIFI_STA) == ESP_OK) {
        char buf[18];
        snprintf(buf, sizeof(buf), MACSTR, MAC2STR(mac));
        j.key("mac").str(buf);
    }
    j.end_obj();
    return mesp_web_send_json(req, j.out());
}

/** Configured network and the outcome of the last switch. */
static esp_err_t wifi_get(httpd_req_t *req)
{
    if (!mesp_web_require(req, MESP_ROLE_ADMIN)) return ESP_OK;
    wifi_config_t cfg = {};
    esp_wifi_get_config(WIFI_IF_STA, &cfg);
    const mesp_wifi_switch_t last = mesp_wifi_last_switch();
    Json j;
    j.obj().key("ssid").str((const char *)cfg.sta.ssid).key("connected").boolean(mesp_wifi_connected());
    j.key("switch").obj().key("ssid").str(last.ssid).key("state").str(last.state).end_obj();
    j.end_obj();
    return mesp_web_send_json(req, j.out());
}

/** Networks in range, strongest first, each name once. */
static esp_err_t wifi_scan(httpd_req_t *req)
{
    if (!mesp_web_require(req, MESP_ROLE_ADMIN)) return ESP_OK;
    if (mesp_wifi_switching()) return mesp_web_send_error(req, "409 Conflict", "switching networks, try again shortly");
    wifi_scan_config_t scan = {};
    scan.show_hidden = false;
    esp_err_t err = esp_wifi_scan_start(&scan, true);
    if (err != ESP_OK) return mesp_web_send_error(req, "500 Internal Server Error", esp_err_to_name(err));
    uint16_t count = 30;
    auto *aps = new wifi_ap_record_t[count];
    esp_wifi_scan_get_ap_records(&count, aps); // sorted by signal strength
    Json j;
    j.obj().key("networks").arr();
    for (uint16_t i = 0; i < count; i++) {
        const char *ssid = (const char *)aps[i].ssid;
        bool dup = !*ssid;
        for (uint16_t k = 0; k < i && !dup; k++) dup = strcmp(ssid, (const char *)aps[k].ssid) == 0;
        if (dup) continue;
        j.obj().key("ssid").str(ssid).key("rssi").num(aps[i].rssi).key("channel").num(aps[i].primary);
        j.key("auth").str(auth_name(aps[i].authmode)).end_obj();
    }
    j.end_arr().end_obj();
    delete[] aps;
    return mesp_web_send_json(req, j.out());
}

/** Switch to another network (or password): tried first, the previous one stays as fallback. */
static esp_err_t wifi_post(httpd_req_t *req)
{
    if (!mesp_web_require(req, MESP_ROLE_ADMIN)) return ESP_OK;
    std::string body, ssid, password;
    if (!mesp_web_read_body(req, body)) return ESP_OK;
    mesp_web_param(body, "ssid", ssid);
    mesp_web_param(body, "password", password);
    if (ssid.empty() || ssid.size() > 32) return mesp_web_send_error(req, "400 Bad Request", "invalid network name");
    if (password.size() > 63 || (!password.empty() && password.size() < 8)) {
        return mesp_web_send_error(req, "400 Bad Request", "the password needs 8 to 63 characters");
    }
    const esp_err_t err = mesp_wifi_switch(ssid.c_str(), password.c_str());
    if (err == ESP_ERR_INVALID_STATE) return mesp_web_send_error(req, "409 Conflict", "already switching networks");
    if (err != ESP_OK) return mesp_web_send_error(req, "500 Internal Server Error", "out of memory");
    Json j;
    j.obj().key("ok").boolean(true).key("timeout").num(MESP_WIFI_SWITCH_TIMEOUT_S).end_obj();
    return mesp_web_send_json(req, j.out());
}

void mesp_wifi_register_web()
{
    mesp_web_add("/api/wifi", HTTP_GET, wifi_get);
    mesp_web_add("/api/wifi", HTTP_POST, wifi_post);
    mesp_web_add("/api/wifi/scan", HTTP_GET, wifi_scan);
    mesp_web_add("/api/wifi/status", HTTP_GET, wifi_status);
}
